<script setup>
import {computed,ref,watch} from 'vue'
import {parse,defaults} from './parser.js'
const uuid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')
const key='fxtool-v1',error=ref(''),notice=ref('')
let initial={modules:[],settings:structuredClone(defaults)}
try{const saved=localStorage.getItem(key);if(saved){const data=JSON.parse(saved);if(!Array.isArray(data.modules)||!data.settings)throw Error();initial=data}}catch{error.value='本地数据无法读取，请先导出备份后处理；当前不会自动覆盖原数据。'}
const state=ref(initial),storageBlocked=ref(!!error.value),activeId=ref(null),name=ref(''),input=ref(''),showSettings=ref(false)
const dateString=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const today=dateString(new Date()),start=ref(today),end=ref(today)
const active=computed(()=>state.value.modules.find(m=>m.id===activeId.value))
watch(state,()=>{if(storageBlocked.value)return;try{localStorage.setItem(key,JSON.stringify(state.value));error.value=''}catch{error.value='保存失败：存储空间不足或本地存储被禁用。请导出备份，暂勿关闭页面。'}},{deep:true,flush:'sync'})
const money=n=>(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const total=m=>m.records.reduce((sum,r)=>sum+r.total,0)
const allTotal=computed(()=>state.value.modules.reduce((sum,m)=>sum+total(m),0))
const preview=computed(()=>{try{return{rows:parse(input.value,state.value.settings),error:''}}catch(e){return{rows:[],error:e.message}}})
const previewTotal=computed(()=>preview.value.rows.reduce((s,r)=>s+r.total,0))
const rows=computed(()=>(active.value?.records||[]).filter(r=>{const d=dateString(new Date(r.createdAt));return(!start.value||d>=start.value)&&(!end.value||d<=end.value)}).sort((a,b)=>b.createdAt-a.createdAt))
const filteredTotal=computed(()=>rows.value.reduce((s,r)=>s+r.total,0))
function addModule(){const title=name.value.trim();if(!title)return;if(state.value.modules.some(m=>m.name===title)){notice.value='该模块名称已存在';return}state.value.modules.push({id:uuid(),name:title,createdAt:Date.now(),records:[]});name.value='';notice.value='模块已添加'}
function removeModule(m){if(confirm(`删除「${m.name}」及其全部记录？此操作无法撤销。`))state.value.modules=state.value.modules.filter(x=>x.id!==m.id)}
function save(){if(!active.value||preview.value.error||!preview.value.rows.length)return;active.value.records.push(...preview.value.rows.map(r=>({...r,id:uuid(),createdAt:Date.now()})));input.value='';notice.value='记录已保存到本机'}
function removeRecord(r){if(confirm('确定删除这条记录？'))active.value.records=active.value.records.filter(x=>x.id!==r.id)}
function clear(){if(confirm('清除所有模块、记录和解析设置？此操作无法撤销，请先备份。')){storageBlocked.value=false;state.value={modules:[],settings:structuredClone(defaults)};activeId.value=null;notice.value='所有数据已清除'}}
function exportData(){if(window.AndroidBackup){window.AndroidBackup.saveJson(JSON.stringify(state.value,null,2));return}const url=URL.createObjectURL(new Blob([JSON.stringify(state.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`分项记账-${today}.json`;a.click();URL.revokeObjectURL(url)}
async function importData(e){const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.modules)||!Array.isArray(data.settings?.markers)||!Array.isArray(data.settings?.separators)||data.modules.some(m=>typeof m.name!=='string'||!Array.isArray(m.records)||m.records.some(r=>!Array.isArray(r.items)||!Number.isSafeInteger(r.total)||!Number.isSafeInteger(r.cents)||!Number.isFinite(r.createdAt))))throw Error();if(confirm('使用备份覆盖当前所有数据？')){storageBlocked.value=false;state.value=data;activeId.value=null;notice.value='备份已恢复'}}catch{notice.value='备份格式无效，未更改当前数据'}e.target.value=''}
function updateSetting(field,value){const values=value.split('\n').filter(s=>s.length);if(values.length)state.value.settings[field]=[...new Set(values)]}
</script>

<template>
 <div class="app-shell">
  <aside><div class="brand"><span class="brand-icon">分</span><div>分项记账<small>FXTOOL · LOCAL LEDGER</small></div></div><div class="workspace-label">工作空间</div><button class="nav" :class="{selected:!active}" @click="activeId=null">▦ <span>我的模块</span><b>{{state.modules.length}}</b></button><div class="side-modules"><button v-for="m in state.modules" :key="m.id" :class="{selected:activeId===m.id}" @click="activeId=m.id"><span>◈</span>{{m.name}}</button></div><div class="local-badge"><i></i> 本地存储 · 离线可用<small>所有记录仅保存在当前设备</small></div></aside>
  <main><header><div class="breadcrumb">工作空间 <span>/</span> <b>{{active?active.name:'我的模块'}}</b></div><button class="text-button" @click="showSettings=!showSettings">⚙ 解析设置</button></header>
   <div class="content"><div class="heading"><div><div class="eyebrow">{{active?'MODULE DETAILS':'YOUR WORKSPACE'}}</div><h1>{{active?active.name:'我的模块'}}<span class="pill">本地账本</span></h1><p>{{active?'输入内容，自动拆分号码并计算每项金额。':'把不同的记录分开管理，每一笔都清晰有序。'}}</p></div><div class="actions"><button @click="exportData">↓ 导出备份</button><label class="button">↑ 恢复备份<input type="file" accept=".json" hidden @change="importData"></label><button class="danger-light" @click="clear">清除缓存</button></div></div>
    <div v-if="error" class="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}<button @click="notice=''">×</button></div>
    <section v-if="showSettings" class="card settings"><h3>解析规则</h3><p>每行一个元素。连接符可填写点号、空格等；金额分隔词如「各」「每」。设置后立即生效。</p><div class="settings-grid"><label>号码连接符<textarea :value="state.settings.separators.join('\n')" @change="updateSetting('separators',$event.target.value)"></textarea></label><label>金额分隔词<textarea :value="state.settings.markers.join('\n')" @change="updateSetting('markers',$event.target.value)"></textarea></label></div></section>
    <template v-if="!active"><div class="stats"><div class="stat primary"><span>全部模块累计金额</span><strong><small>¥</small> {{money(allTotal)}}</strong><div>来自 {{state.modules.length}} 个模块的全部记录</div></div><div class="stat"><span>模块数量</span><strong>{{state.modules.length}} <small>个</small></strong><div>独立管理，随时查看</div></div><div class="stat"><span>累计记录</span><strong>{{state.modules.reduce((s,m)=>s+m.records.length,0)}} <small>条</small></strong><div>数据保存在当前设备</div></div></div>
     <section class="card add-module"><div><h3><span class="mini-icon">＋</span> 添加模块</h3><p>为新的记录创建一个专属模块</p></div><form @submit.prevent="addModule"><input v-model="name" maxlength="60" placeholder="输入模块名称，如：日常记录" required><button class="green">＋ 添加模块</button></form></section>
     <section class="card"><div class="section-title"><h3>模块列表 <span>{{state.modules.length}}</span></h3><small>点击模块名称查看详情 →</small></div><div class="table-scroll"><table><thead><tr><th>模块名称</th><th>记录数</th><th>创建时间</th><th class="right">累计金额</th><th class="right">操作</th></tr></thead><tbody><tr v-for="m in state.modules" :key="m.id"><td><button class="module-link" @click="activeId=m.id"><span>◈</span>{{m.name}} <small>↗</small></button></td><td>{{m.records.length}} 条</td><td class="muted">{{new Date(m.createdAt).toLocaleDateString('zh-CN')}}</td><td class="right amount">¥ {{money(total(m))}}</td><td class="right"><button class="delete" @click="removeModule(m)">删除</button></td></tr></tbody></table></div><div v-if="!state.modules.length" class="empty"><div>▦</div><h3>创建你的第一个模块</h3><p>在上方输入名称，即可开始记录</p></div><div class="table-footer">共 {{state.modules.length}} 个模块<span>全部累计 <b>¥ {{money(allTotal)}}</b></span></div></section>
    </template>
    <template v-else><button class="back" @click="activeId=null">← 返回模块列表</button><div class="stats"><div class="stat primary"><span>当前筛选金额</span><strong><small>¥</small> {{money(filteredTotal)}}</strong><div>{{rows.length}} 条记录 · {{start||'最早'}} 至 {{end||'现在'}}</div></div><div class="stat"><span>模块全部金额</span><strong><small>¥</small> {{money(total(active))}}</strong><div>{{active.records.length}} 条累计记录</div></div></div>
     <section class="card entry"><div class="section-title"><h3>添加内容</h3><small>输入后自动解析 · 支持多行</small></div><textarea v-model="input" class="entry-input" placeholder="例如：12.23.32.45.12.1各50&#10;每行输入一组内容"></textarea><div v-if="preview.error" class="parse-error">{{preview.error}}</div><div v-for="(r,i) in preview.rows" :key="i" class="parsed"><div class="number-grid"><div v-for="(n,j) in r.items" :key="j"><strong>{{n}}</strong><span>{{money(r.cents)}}</span></div></div><div class="row-total"><small>总计</small><b>¥ {{money(r.total)}}</b></div></div><div class="entry-footer"><small>待保存合计 <b>¥ {{money(previewTotal)}}</b></small><button class="green" :disabled="!preview.rows.length||!!preview.error||storageBlocked" @click="save">＋ 保存记录</button></div></section>
     <section class="card"><div class="section-title filter-title"><h3>内容记录 <span>{{rows.length}}</span></h3><div class="filters"><input v-model="start" aria-label="开始日期" type="date"><span>至</span><input v-model="end" aria-label="结束日期" type="date"><button @click="start=today;end=today">今天</button><button @click="start='';end=''">全部</button></div></div><p v-if="start&&end&&start>end" class="parse-error">开始日期不能晚于结束日期</p><div v-for="r in rows" :key="r.id" class="record"><div class="record-head"><span>{{new Date(r.createdAt).toLocaleString('zh-CN')}}</span><button class="delete" @click="removeRecord(r)">删除</button></div><div class="parsed"><div class="number-grid"><div v-for="(n,i) in r.items" :key="i"><strong>{{n}}</strong><span>{{money(r.cents)}}</span></div></div><div class="row-total"><small>总计</small><b>¥ {{money(r.total)}}</b></div></div><p class="source">原文：{{r.source}}</p></div><div v-if="!rows.length" class="empty"><div>≡</div><h3>当前时间范围暂无记录</h3><p>添加一条内容，或调整时间筛选</p></div><div class="table-footer">当前筛选 {{rows.length}} 条<span>合计 <b>¥ {{money(filteredTotal)}}</b></span></div></section>
    </template><footer>分项记账 · 数据属于你，保存在本机 <span>建议定期导出备份</span></footer>
   </div>
  </main>
 </div>
</template>
